-- Warehouse items: the restaurant's purchasing list (names, units, categories) is put back into the stockroom so a
-- purchase request has its items ready. They are warehouse-only: `mfg = false` keeps them out of recipes and out of
-- every manufacturing screen until a manager switches an item on. No prices and no quantities come with them.

alter table public.stock_items add column if not exists mfg boolean not null default true;

insert into public.stock_items (id, restaurant_id, name, sku, category, kind, base_unit, packs, count_unit, account, levels, branch_levels,
                                supplier_ids, preferred_supplier_id, last_cost, default_location_ids, track_batches, shelf_life_days,
                                vat_bp, yield_bp, allergens, active, note, market_key, mfg)
